1	// `roster review <repo> --observational`: fetch → parse → identify → score, then reports/<slug>/.
2	// Every stage is a TOOL span inside one WORKFLOW review span (DESIGN.md §"Observability (neatlogs)").
3	import { join, resolve } from "node:path";
4	import type { Command } from "../cli.ts";
5	import { priceSession } from "../price/index.ts";
6	import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
7	import { fetchCheckpoints } from "../ingest/fetch.ts";
8	import { type ParsedSession, parseCheckpoints } from "../ingest/parse.ts";
9	import { type Identity, identify, inferenceAccuracy } from "../identity/index.ts";
10	import { survival } from "../score/survival.ts";
11	import { reverted } from "../score/revert.ts";
12	import { rework } from "../score/rework.ts";
13	import { buildSetupRows, buildTags, repoSlug, type ReviewReport, slugDir, writeReview } from "../review/export.ts";
14	import type { Outcome, Review, Session } from "../types.ts";
15	
16	export const DEFAULT_CACHE = ".roster/cache";
17	/** Mature = at least this many first-parent commits after the session's commit, and this many seconds older than HEAD. */
18	export const MIN_DEPTH = 5;
19	export const MIN_AGE_S = 6 * 3600;
20	
21	const STAGES = ["fetch", "parse", "identify", "score"] as const;
22	type Stage = (typeof STAGES)[number];
23	
24	const USAGE = `usage: roster review <repo> --observational [--out <dir>] [--cache <dir>]
25	
26	  <repo>            a git URL or a local path to a repo that has Entire checkpoints
27	  --observational   score sessions that already exist (evidence level A). Required for now.
28	  --out <dir>       where to write review.json, review.md, sessions.json and outcomes.json
29	                    (default reports/<slug>)
30	  --cache <dir>     fetch cache (default ${DEFAULT_CACHE})`;
31	
32	export interface ReviewArgs {
33	  repo: string;
34	  out: string | undefined;
35	  cache: string;
36	}
37	
38	/** Thrown for bad arguments. The CLI prints the message and exits 2. */
39	export class UsageError extends Error {}
40	
41	/** Parses the arguments after `review`. Throws UsageError on anything it does not accept. */
42	export function parseReviewArgs(args: string[]): ReviewArgs {
43	  let repo: string | undefined;
44	  let observational = false;
45	  let out: string | undefined;
46	  let cache = DEFAULT_CACHE;
47	  for (let i = 0; i < args.length; i++) {
48	    const a = args[i]!;
49	    const eq = a.indexOf("=");
50	    const name = eq === -1 ? a : a.slice(0, eq);
51	    // A flag takes its value inline (--out=dir) or as the next argument (--out dir).
52	    const takeValue = (): string => {
53	      if (eq !== -1) return a.slice(eq + 1);
54	      const v = args[++i];
55	      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
56	      return v;
57	    };
58	    if (name === "--observational" && eq === -1) observational = true;
59	    else if (name === "--out") out = takeValue();
60	    else if (name === "--cache") cache = takeValue();
61	    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
62	    else if (repo === undefined) repo = a;
63	    else throw new UsageError(`unexpected argument ${a}`);
64	  }
65	  if (repo === undefined) throw new UsageError("missing <repo>");
66	  if (!observational) {
67	    throw new UsageError("only --observational is implemented; the controlled replay path is not built yet");
68	  }
69	  return { repo, out, cache };
70	}
71	
72	const NO_DATA =
73	  "no Entire data found. Run `entire enable` in the source repo, push its entire/checkpoints/v1 branch, and try again.";
74	
75	function git(repo: string, args: string[]): string {
76	  const p = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
77	  if (p.exitCode !== 0) throw new Error(`git ${args[0]} failed: ${p.stderr.toString().trim()}`);
78	  return p.stdout.toString();
79	}
80	
81	interface ScoreContext {
82	  repo: string;
83	  head: string;
84	  headTime: number;
85	}
86	
87	const tooYoung = (session_id: string): Outcome => ({
88	  session_id,
89	  status: "too_young",
90	  survival: null,
91	  reverted: null,
92	  rework_human: null,
93	  rework_agent: null,
94	  unattended: null,
95	  tests_at_commit: null,
96	  difficulty: null,
97	  tercile: null,
98	});
99	
100	/**
101	 * Scores one session from its commit. Sessions without a trailer-linked commit, and commits that are not yet
102	 * mature, come back too_young with null metrics. Throws when git cannot read the commit.
103	 */
104	export function scoreSession(session: ParsedSession, ctx: ScoreContext): Outcome {
105	  const sha = session.commit_sha;
106	  if (sha === null) return tooYoung(session.id);
107	  const depth = Number(git(ctx.repo, ["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]).trim());
108	  const age = ctx.headTime - Number(git(ctx.repo, ["show", "-s", "--format=%ct", sha]).trim());
109	  if (depth < MIN_DEPTH || age < MIN_AGE_S) return tooYoung(session.id);
110	
111	  const surv = survival(ctx.repo, [sha], ctx.head);
112	  const rw = rework(ctx.repo, sha);
113	  return {
114	    session_id: session.id,
115	    status: "mature",
116	    survival: surv.ratio,
117	    reverted: reverted(ctx.repo, sha),
118	    rework_human: rw.human,
119	    rework_agent: rw.agent,
120	    unattended: session.n_user_prompts === 1,
121	    tests_at_commit: null,
122	    difficulty: null,
123	    tercile: null,
124	  };
125	}
126	
127	const pct = (x: number) => `${(100 * x).toFixed(1)}%`;
128	
129	async function stage<T>(n: number, name: Stage, repo: string, work: () => Promise<[T, string]>): Promise<T> {
130	  return withSpan("TOOL", name, { repo }, async () => {
131	    const [value, detail] = await work();
132	    console.log(`[${n}/${STAGES.length}] ${name}: ${detail}`);
133	    return value;
134	  });
135	}
136	
137	/** Runs the whole review. Resolves to the exit code; writes reports only when every stage succeeds. */
138	export async function runReview(args: ReviewArgs): Promise<number> {
139	  const label = repoSlug(args.repo);
140	  const outDir = resolve(args.out ?? join("reports", slugDir(label)));
141	  const createdAt = new Date().toISOString();
142	  const reviewId = `${slugDir(label)}-${createdAt.replace(/\D/g, "").slice(0, 14)}`;
143	
144	  await initObs({ workflowName: "roster-review" });
145	  setSession(reviewId);
146	  console.log(`roster review ${label} (${reviewId}) → ${outDir}`);
147	  try {
148	    return await withSpan("WORKFLOW", "review", { repo: label }, async () => {
149	      const fetched = await stage(1, "fetch", label, async () => {
150	        const f = await fetchCheckpoints(args.repo, { cacheDir: resolve(args.cache) });
151	        return [f, `backend=${f.backend} head=${f.headSha.slice(0, 12) || "none"}`];
152	      });
153	      if (fetched.backend === "none") {
154	        console.error(`roster review: ${NO_DATA}`);
155	        return 1;
156	      }
157	      if (fetched.headSha === "") {
158	        console.error("roster review: the repo has checkpoints but no HEAD commit to score them against");
159	        return 1;
160	      }
161	
162	      const sessions = await stage(2, "parse", label, async () => {
163	        const parsed = parseCheckpoints(fetched.repoPath, fetched.backend === "refs" ? "git-refs" : "branch");
164	        return [parsed, `${parsed.length} sessions`];
165	      });
166	
167	      const identities: Identity[] = await stage(3, "identify", label, async () => {
168	        const ids = sessions.map((s) => identify(s, fetched.repoPath));
169	        const setups = new Set(ids.map((i) => i.setupId).filter((x): x is string => x !== null)).size;
170	        const acc = inferenceAccuracy(ids);
171	        return [ids, `${setups} setups, tag accuracy ${acc === null ? "n/a (no tagged sessions)" : pct(acc)}`];
172	      });
173	
174	      const headTime = Number(git(fetched.repoPath, ["show", "-s", "--format=%ct", fetched.headSha]).trim());
175	      const ctx: ScoreContext = { repo: fetched.repoPath, head: fetched.headSha, headTime };
176	      const scored = await stage(4, "score", label, async () => {
177	        const out: Session[] = [];
178	        const outcomes: Outcome[] = [];
179	        const failed: string[] = [];
180	        sessions.forEach((s, i) => {
181	          const id = identities[i]!;
182	          const cost = priceSession(s.model, {
183	            input: s.tokens_in,
184	            output: s.tokens_out,
185	            cache_read: s.cache_read,
186	            cache_write: s.cache_write,
187	          }).usd;
188	          out.push({ ...stripParsed(s), setup_id: id.setupId, cost_usd: cost });
189	          try {
190	            outcomes.push(scoreSession(s, ctx));
191	          } catch (err) {
192	            failed.push(`${s.id}: ${err instanceof Error ? err.message : String(err)}`);
193	            outcomes.push(tooYoung(s.id));
194	          }
195	        });
196	        const mature = outcomes.filter((o) => o.status === "mature").length;
197	        return [
198	          { out, outcomes, failed },
199	          `${mature} mature, ${outcomes.length - mature} too young${failed.length ? `, ${failed.length} failed` : ""}`,
200	        ];
201	      });
202	
203	      const notes = [
204	        `${scored.outcomes.filter((o) => o.status === "too_young").length} sessions are too young or have no commit: a session is mature at ≥ ${MIN_DEPTH} first-parent commits and ≥ ${MIN_AGE_S / 3600} h before HEAD`,
205	        ...scored.failed.map((f) => `could not be scored: ${f}`),
206	        `${scored.out.filter((s) => s.cost_usd === null).length} sessions have no price (unknown model, or a price that depends on prompt size)`,
207	        `${scored.out.filter((s) => s.setup_id === null).length} sessions have no setup because their rules hash is unknown`,
208	      ];
209	      const tags = buildTags(scored.out);
210	      const review: Review = {
211	        id: reviewId,
212	        repo: label,
213	        created_at: createdAt,
214	        generated_at: createdAt,
215	        has_entire_data: true,
216	        setups: buildSetupRows(scored.out, scored.outcomes),
217	        ...(tags ? { tags } : {}),
218	        label: "insufficient_data",
219	        suspect: null,
220	        odds_ratio: null,
221	        ci95: null,
222	        p_value: null,
223	        evidence_level: "A",
224	      };
225	      const report: ReviewReport = {
226	        review,
227	        note:
228	          "No suspect call. The difficulty-matched Mantel–Haenszel test (DESIGN.md §\"Difficulty and review\") is not part of this command yet, so the setup numbers below are descriptive only.",
229	        sessions: scored.out,
230	        outcomes: scored.outcomes,
231	        notes,
232	      };
233	      const written = writeReview(outDir, report);
234	      console.log(`wrote ${written.join(", ")}`);
235	      console.log(`label ${review.label} · evidence level ${review.evidence_level}`);
236	      return 0;
237	    });
238	  } finally {
239	    await flushObs();
240	  }
241	}
242	
243	/** A ParsedSession without the parse-only fields, so sessions.json holds Session rows. */
244	function stripParsed(s: ParsedSession): Session {
245	  const { usage_source: _usage, model_source: _model, ...session } = s;
246	  return session;
247	}
248	
249	export const reviewCommand: Command = {
250	  name: "review",
251	  summary: "score a repo's agent sessions (--observational)",
252	  usage: USAGE,
253	  async run(args) {
254	    let parsed: ReviewArgs;
255	    try {
256	      parsed = parseReviewArgs(args);
257	    } catch (err) {
258	      if (!(err instanceof UsageError)) throw err;
259	      console.error(`roster review: ${err.message}\n\n${USAGE}`);
260	      return 2;
261	    }
262	    return runReview(parsed);
263	  },
264	};
