1	// Writes one observational review to reports/<slug>/: review.json (the Review type, validated before
2	// it is written), sessions.json, outcomes.json and review.md. See docs/DESIGN.md §"Data model" and §"Review".
3	import { mkdirSync, writeFileSync } from "node:fs";
4	import { basename, join, resolve } from "node:path";
5	import { inferenceAccuracy, parseTag } from "../identity/index.ts";
6	import { aggregateBySetup, type ScoredOutcome, sessionCostDetail, UNKNOWN_SETUP } from "../score/index.ts";
7	import type { EvidenceLevel, Outcome, Review, ReviewLabel, ReviewTags, Session, SetupRow } from "../types.ts";
8	
9	/** Keys of the Review type in src/types.ts. Kept in step by the `satisfies Review` check in tests. */
10	export const REVIEW_KEYS = [
11	  "id",
12	  "repo",
13	  "created_at",
14	  "generated_at",
15	  "has_entire_data",
16	  "setups",
17	  "label",
18	  "suspect",
19	  "odds_ratio",
20	  "ci95",
21	  "p_value",
22	  "evidence_level",
23	] as const;
24	
25	/** Keys that may be absent: `tags` is written only when sessions carry prompt tags. */
26	export const OPTIONAL_REVIEW_KEYS = ["tags"] as const;
27	
28	export const SETUP_ROW_KEYS = [
29	  "setup_id",
30	  "label",
31	  "harness",
32	  "model",
33	  "rules_hash",
34	  "sessions",
35	  "mature_sessions",
36	  "spend_usd",
37	  "priced_sessions",
38	  "spend_lower_bound",
39	  "unattended",
40	  "survival",
41	  "reverted",
42	  "rework_human",
43	  "surviving_changes",
44	  "cost_per_surviving_change",
45	  "evidence_level",
46	] as const satisfies readonly (keyof SetupRow)[];
47	
48	const LABELS: readonly ReviewLabel[] = ["suspect", "no_suspect", "insufficient_data"];
49	const EVIDENCE: readonly EvidenceLevel[] = ["A", "B", "C"];
50	
51	const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
52	const isFiniteNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
53	
54	/** "owner/name" for a GitHub URL, otherwise the last path segment. */
55	export function repoLabel(repo: string): string {
56	  const trimmed = repo.trim();
57	  const remote = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?\/?$/.exec(trimmed);
58	  if (remote) return `${remote[1]}/${remote[2]}`;
59	  return basename(trimmed.replace(/\/+$/, "").replace(/\.git$/, ""));
60	}
61	
62	const URL_FORM = /^[a-z][a-z0-9+.-]*:\/\/|^[^/@\s]+@[^/:\s]+:/i;
63	
64	/** "owner/name" from an https, ssh:// or scp-style (git@host:owner/name) remote URL; null for anything else. */
65	export function parseRemote(url: string): string | null {
66	  const u = url.trim();
67	  if (!URL_FORM.test(u)) return null;
68	  const m = /[/:]([^/:\s]+)\/([^/\s]+?)(?:\.git)?\/?$/.exec(u);
69	  return m ? `${m[1]}/${m[2]}` : null;
70	}
71	
72	/**
73	 * The review's repo slug "owner/name". A URL is parsed directly. A local path uses its `origin` remote, and with
74	 * no remote (or one that does not parse) falls back to the directory's basename.
75	 */
76	export function repoSlug(repo: string): string {
77	  const direct = parseRemote(repo);
78	  if (direct !== null) return direct;
79	  const dir = resolve(repo);
80	  const p = Bun.spawnSync(["git", "remote", "get-url", "origin"], { cwd: dir, stdout: "pipe", stderr: "pipe" });
81	  const remote = p.exitCode === 0 ? parseRemote(p.stdout.toString()) : null;
82	  return remote ?? basename(dir);
83	}
84	
85	/** Directory name under reports/ for a repo slug: "owner__name", or the bare name. */
86	export function slugDir(slug: string): string {
87	  return slug.replace("/", "__").replace(/[^A-Za-z0-9._-]+/g, "-");
88	}
89	
90	/** Directory name under reports/: "owner__name" for GitHub repos (the web app's lookup form), else the basename. */
91	export function reviewSlug(repo: string): string {
92	  return repoLabel(repo).replace("/", "__").replace(/[^A-Za-z0-9._-]+/g, "-");
93	}
94	
95	const RATE_KEYS = ["unattended", "survival", "reverted", "rework_human"] as const;
96	
97	function validateSetupRow(row: unknown, at: string): string[] {
98	  if (!isRecord(row)) return [`${at} must be an object`];
99	  const errs: string[] = [];
100	  for (const k of SETUP_ROW_KEYS) if (!(k in row)) errs.push(`${at} missing ${k}`);
101	  for (const k of Object.keys(row)) if (!(SETUP_ROW_KEYS as readonly string[]).includes(k)) errs.push(`${at} unexpected key ${k}`);
102	  for (const k of ["setup_id", "label", "harness", "model"] as const) {
103	    if (typeof row[k] !== "string" || row[k] === "") errs.push(`${at}.${k} must be a non-empty string`);
104	  }
105	  if (row.rules_hash !== null && typeof row.rules_hash !== "string") errs.push(`${at}.rules_hash must be a string or null`);
106	  for (const k of ["sessions", "mature_sessions"] as const) {
107	    if (!Number.isInteger(row[k]) || (row[k] as number) < 0) errs.push(`${at}.${k} must be a non-negative integer`);
108	  }
109	  if (isFiniteNum(row.sessions) && isFiniteNum(row.mature_sessions) && row.mature_sessions > row.sessions) {
110	    errs.push(`${at}.mature_sessions exceeds sessions`);
111	  }
112	  if (row.spend_usd !== null && !(isFiniteNum(row.spend_usd) && row.spend_usd >= 0)) {
113	    errs.push(`${at}.spend_usd must be null or a number >= 0`);
114	  }
115	  for (const k of ["priced_sessions", "surviving_changes"] as const) {
116	    if (!isFiniteNum(row[k]) || row[k] < 0) errs.push(`${at}.${k} must be a number >= 0`);
117	  }
118	  if (typeof row.spend_lower_bound !== "boolean") errs.push(`${at}.spend_lower_bound must be a boolean`);
119	  if (isFiniteNum(row.priced_sessions) && isFiniteNum(row.sessions) && row.priced_sessions > row.sessions) {
120	    errs.push(`${at}.priced_sessions exceeds sessions`);
121	  }
122	  if (row.cost_per_surviving_change !== null && !(isFiniteNum(row.cost_per_surviving_change) && row.cost_per_surviving_change >= 0)) {
123	    errs.push(`${at}.cost_per_surviving_change must be null or a number >= 0`);
124	  }
125	  for (const k of RATE_KEYS) {
126	    const v = row[k];
127	    if (v !== null && !(isFiniteNum(v) && v >= 0 && v <= 1)) errs.push(`${at}.${k} must be null or a number in [0, 1]`);
128	    if (row.mature_sessions === 0 && v !== null) errs.push(`${at}.${k} must be null when mature_sessions is 0`);
129	  }
130	  if (!(EVIDENCE as readonly unknown[]).includes(row.evidence_level)) errs.push(`${at}.evidence_level must be A, B or C`);
131	  return errs;
132	}
133	
134	function validTags(t: unknown): boolean {
135	  if (!isRecord(t) || !isRecord(t.by_tag)) return false;
136	  if (t.tag_accuracy !== null && !(isFiniteNum(t.tag_accuracy) && t.tag_accuracy >= 0 && t.tag_accuracy <= 1)) return false;
137	  return Object.values(t.by_tag).every(
138	    (v) => isRecord(v) && Number.isInteger(v.sessions) && Array.isArray(v.setup_ids) && v.setup_ids.every((x) => typeof x === "string"),
139	  );
140	}
141	
142	/** Lists every way `value` fails the Review type. An empty list means it validates. */
143	export function validateReview(value: unknown): string[] {
144	  if (!isRecord(value)) return ["review must be an object"];
145	  const errs: string[] = [];
146	  for (const k of REVIEW_KEYS) if (!(k in value)) errs.push(`missing ${k}`);
147	  const allowed: readonly string[] = [...REVIEW_KEYS, ...OPTIONAL_REVIEW_KEYS];
148	  for (const k of Object.keys(value)) if (!allowed.includes(k)) errs.push(`unexpected key ${k}`);
149	
150	  for (const k of ["id", "repo", "created_at", "generated_at"] as const) {
151	    if (typeof value[k] !== "string" || value[k] === "") errs.push(`${k} must be a non-empty string`);
152	  }
153	  for (const k of ["created_at", "generated_at"] as const) {
154	    if (typeof value[k] === "string" && Number.isNaN(Date.parse(value[k]))) errs.push(`${k} is not a date`);
155	  }
156	  if (typeof value.has_entire_data !== "boolean") errs.push("has_entire_data must be a boolean");
157	  if (!Array.isArray(value.setups)) errs.push("setups must be an array");
158	  else value.setups.forEach((row, i) => errs.push(...validateSetupRow(row, `setups[${i}]`)));
159	  if ("tags" in value && !validTags(value.tags)) errs.push("tags must be { by_tag, tag_accuracy }");
160	
161	  const label = value.label;
162	  if (!(LABELS as readonly unknown[]).includes(label)) errs.push(`label must be one of ${LABELS.join(", ")}`);
163	  if (label === "suspect") {
164	    if (typeof value.suspect !== "string" || value.suspect === "") errs.push("suspect must name a setup when label is suspect");
165	    if (!isFiniteNum(value.odds_ratio)) errs.push("odds_ratio must be a number when label is suspect");
166	    if (!Array.isArray(value.ci95)) errs.push("ci95 must be set when label is suspect");
167	    if (!isFiniteNum(value.p_value)) errs.push("p_value must be a number when label is suspect");
168	  } else if (value.suspect !== null) {
169	    errs.push("suspect must be null unless label is suspect");
170	  }
171	
172	  if (value.odds_ratio !== null && !(isFiniteNum(value.odds_ratio) && value.odds_ratio >= 0)) {
173	    errs.push("odds_ratio must be null or a number >= 0");
174	  }
175	  const ci = value.ci95;
176	  if (ci !== null) {
177	    const ok = Array.isArray(ci) && ci.length === 2 && ci.every(isFiniteNum) && ci[0]! <= ci[1]!;
178	    if (!ok) errs.push("ci95 must be null or [low, high] with low <= high");
179	  }
180	  if (value.p_value !== null && !(isFiniteNum(value.p_value) && value.p_value >= 0 && value.p_value <= 1)) {
181	    errs.push("p_value must be null or a number in [0, 1]");
182	  }
183	  if (!(EVIDENCE as readonly unknown[]).includes(value.evidence_level)) errs.push("evidence_level must be A, B or C");
184	  return errs;
185	}
