187	/** Per-setup numbers for review.md. Rates are null when no mature session supports them. */
188	export interface SetupSummary {
189	  setup_id: string;
190	  label: string;
191	  sessions: number;
192	  mature: number;
193	  spend_usd: number;
194	  unpriced: number;
195	  /** Mean survival over mature sessions. */
196	  survival: number | null;
197	  /** Share of mature sessions that were reverted. */
198	  reverted: number | null;
199	  /** Mean human rework share over mature sessions. */
200	  rework_human: number | null;
201	  /** Share of mature sessions that needed exactly one user prompt. */
202	  unattended: number | null;
203	}
204	
205	const mean = (xs: number[]): number | null => (xs.length === 0 ? null : xs.reduce((a, b) => a + b, 0) / xs.length);
206	
207	/** Groups sessions by setup_id. Sessions with no setup are left out; the caller counts them. */
208	export function summarizeSetups(sessions: Session[], outcomes: Outcome[]): SetupSummary[] {
209	  const byId = new Map<string, Outcome>(outcomes.map((o) => [o.session_id, o]));
210	  const groups = new Map<string, Session[]>();
211	  for (const s of sessions) {
212	    if (s.setup_id === null) continue;
213	    (groups.get(s.setup_id) ?? groups.set(s.setup_id, []).get(s.setup_id)!).push(s);
214	  }
215	  return [...groups]
216	    .sort(([a], [b]) => a.localeCompare(b))
217	    .map(([setup_id, group]) => {
218	      const outs = group.map((s) => byId.get(s.id)).filter((o): o is Outcome => o?.status === "mature");
219	      const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
220	      const survival = outs.map((o) => o.survival).filter((x): x is number => x !== null);
221	      const reverted = outs.map((o) => o.reverted).filter((x): x is boolean => x !== null);
222	      const human = outs.map((o) => o.rework_human).filter((x): x is number => x !== null);
223	      const unattended = outs.map((o) => o.unattended).filter((x): x is boolean => x !== null);
224	      const priced = group.map((s) => s.cost_usd).filter((x): x is number => x !== null);
225	      const first = group[0]!;
226	      return {
227	        setup_id,
228	        label: `${first.harness} · ${first.model}`,
229	        sessions: group.length,
230	        mature: outs.length,
231	        spend_usd: sum(priced),
232	        unpriced: group.length - priced.length,
233	        survival: mean(survival),
234	        reverted: reverted.length === 0 ? null : reverted.filter(Boolean).length / reverted.length,
235	        rework_human: mean(human),
236	        unattended: unattended.length === 0 ? null : unattended.filter(Boolean).length / unattended.length,
237	      };
238	    });
239	}
