241	/**
242	 * One row per known setup, built with aggregateBySetup. Sessions with no setup are left out (the review notes
243	 * count them). Rates are fractions of mature sessions; rework_human is the mean over mature sessions that have it.
244	 */
245	export function buildSetupRows(sessions: Session[], outcomes: Outcome[]): SetupRow[] {
246	  const byId = new Map<string, Outcome>(outcomes.map((o) => [o.session_id, o]));
247	  const scored: ScoredOutcome[] = [];
248	  for (const s of sessions) {
249	    const o = byId.get(s.id);
250	    if (!o || s.setup_id === null) continue;
251	    scored.push({
252	      ...o,
253	      setup_id: s.setup_id,
254	      commit_sha: s.commit_sha,
255	      cost_usd: s.cost_usd,
256	      censored: o.status === "mature" ? null : s.commit_sha === null ? "no_commit" : "too_young",
257	    });
258	  }
259	  const first = new Map<string, Session>();
260	  for (const s of sessions) if (s.setup_id !== null && !first.has(s.setup_id)) first.set(s.setup_id, s);
261	
262	  return aggregateBySetup(scored)
263	    .filter((a) => a.setup_id !== UNKNOWN_SETUP)
264	    .map((a) => {
265	      const s = first.get(a.setup_id)!;
266	      const human = scored
267	        .filter((o) => o.setup_id === a.setup_id && o.status === "mature" && o.rework_human !== null)
268	        .map((o) => o.rework_human as number);
269	      const rate = (n: number) => (a.mature === 0 ? null : n / a.mature);
270	      return {
271	        setup_id: a.setup_id,
272	        label: `${s.harness} · ${s.model}`,
273	        harness: s.harness,
274	        model: s.model,
275	        rules_hash: s.rules_hash,
276	        sessions: a.sessions,
277	        mature_sessions: a.mature,
278	        spend_usd: a.cost_usd,
279	        priced_sessions: a.priced_sessions,
280	        spend_lower_bound: sessions.some(
281	          (x) => x.setup_id === a.setup_id && x.cost_usd !== null && sessionCostDetail({ ...x, cost_usd: null }).lower_bound,
282	        ),
283	        unattended: rate(a.unattended),
284	        survival: a.survival_mean,
285	        reverted: rate(a.reverted),
286	        rework_human: mean(human),
287	        surviving_changes: a.survival_sum,
288	        cost_per_surviving_change: a.cost_per_surviving_change,
289	        evidence_level: "A",
290	      };
291	    });
292	}
