294	/** The `tags` block, or undefined when no session's first prompt carries a `[roster setup=…]` tag. */
295	export function buildTags(sessions: Session[]): ReviewTags | undefined {
296	  const tagged = sessions.map((s) => ({ setupId: s.setup_id, tag: parseTag(s.first_prompt) }));
297	  if (tagged.every((t) => t.tag === null)) return undefined;
298	  const ids = new Map<string, { sessions: number; ids: Set<string> }>();
299	  for (const { setupId, tag } of tagged) {
300	    if (tag === null) continue;
301	    const e = ids.get(tag.setup) ?? ids.set(tag.setup, { sessions: 0, ids: new Set() }).get(tag.setup)!;
302	    e.sessions++;
303	    if (setupId !== null) e.ids.add(setupId);
304	  }
305	  const by_tag = Object.fromEntries(
306	    [...ids].sort(([a], [b]) => a.localeCompare(b)).map(([tag, e]) => [tag, { sessions: e.sessions, setup_ids: [...e.ids].sort() }]),
307	  );
308	  return { by_tag, tag_accuracy: inferenceAccuracy(tagged) };
309	}
