322	const pct = (x: number | null) => (x === null ? "—" : `${(100 * x).toFixed(1)}%`);
323	const usd = (x: number) => `$${x.toFixed(2)}`;
324	const spend = (r: SetupRow) =>
325	  r.spend_usd === null ? `unknown (${r.priced_sessions}/${r.sessions} priced)` : `${r.spend_lower_bound ? "≥ " : ""}${usd(r.spend_usd)}`;
