327	export function renderReviewMarkdown(report: ReviewReport): string {
328	  const { review, note, notes } = report;
329	  const young = (r: SetupRow, v: string) => (r.mature_sessions === 0 ? "too young" : v);
330	  const lines = [
331	    `# Review: ${review.repo}`,
332	    "",
333	    `- Review id: \`${review.id}\``,
334	    `- Created: ${review.created_at}`,
335	    `- Entire data: ${review.has_entire_data ? "yes" : "no"}`,
336	    `- Evidence level: ${review.evidence_level} (observational)`,
337	    `- Label: \`${review.label}\``,
338	    `- Suspect: ${review.suspect ?? "none"}`,
339	    "",
340	    note,
341	    "",
342	    "## Setups",
343	    "",
344	    "| Setup | Harness · model | Sessions | Mature | Spend | Survival | Reverted | Rework (human) | Unattended | $/surviving change | Evidence |",
345	    "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | :---: |",
346	    ...(review.setups ?? buildSetupRows(report.sessions, report.outcomes)).map(
347	      (r) =>
348	        `| \`${r.setup_id}\` | ${r.label} | ${r.sessions} | ${r.mature_sessions} | ${spend(r)} | ${young(r, pct(r.survival))} | ${young(r, pct(r.reverted))} | ${young(r, pct(r.rework_human))} | ${young(r, pct(r.unattended))} | ${r.cost_per_surviving_change === null ? "—" : usd(r.cost_per_surviving_change)} | ${r.evidence_level} |`,
349	    ),
350	    ...(review.tags
351	      ? [
352	          "",
353	          "## Prompt tags",
354	          "",
355	          `Tag accuracy: ${pct(review.tags.tag_accuracy)}`,
356	          "",
357	          "| Tag | Sessions | Inferred setups |",
358	          "| --- | ---: | --- |",
359	          ...Object.entries(review.tags.by_tag).map(([t, v]) => `| \`${t}\` | ${v.sessions} | ${v.setup_ids.map((i) => `\`${i}\``).join(", ") || "—"} |`),
360	        ]
361	      : []),
362	    "",
363	    "## Notes",
364	    "",
365	    ...(notes.length ? notes.map((n) => `- ${n}`) : ["- none"]),
366	    "",
367	  ];
368	  return lines.join("\n");
369	}
