373	/**
374	 * Writes the four report files into `outDir`. Throws, and writes nothing, when review.json fails validation.
375	 * Returns the paths written.
376	 */
377	export function writeReview(outDir: string, report: ReviewReport): string[] {
378	  const problems = validateReview(report.review);
379	  if (problems.length) throw new Error(`review.json does not validate: ${problems.join("; ")}`);
380	  mkdirSync(outDir, { recursive: true });
381	  const files: [string, string][] = [
382	    ["review.json", json(report.review)],
383	    ["sessions.json", json(report.sessions)],
384	    ["outcomes.json", json(report.outcomes)],
385	    ["review.md", renderReviewMarkdown(report)],
386	  ];
387	  return files.map(([name, body]) => {
388	    const path = join(outDir, name);
389	    writeFileSync(path, body);
390	    return path;
391	  });
392	}
